<?php $eyebrow = get_sub_field( 'eyebrow' ); $heading = get_sub_field( 'heading' ); $description = get_sub_field( 'description' ); $items = (array) get_sub_field( 'items' ); $background = get_sub_field( 'background' ); if ( ! $heading && ! $items ) { return; } ?>
<section class="experiences-wrp padding_top_bottom service-v2-industries <?php echo esc_attr( di_service_v2_background_class( $background ) ); ?>"><div class="container"><div class="heading text-center"><?php if ( $eyebrow ) : ?><p class="service-v2-kicker"><?php echo esc_html( $eyebrow ); ?></p><?php endif; ?><?php if ( $heading ) : ?><h2><?php echo esc_html( $heading ); ?></h2><?php endif; ?><?php if ( $description ) : ?><div class="sub_pera"><?php echo wp_kses_post( wpautop( $description ) ); ?></div><?php endif; ?></div><?php if ( $items ) : ?><div class="row"><?php foreach ( $items as $item ) : ?><div class="col-lg-3 col-sm-6"><div class="experiences-btn-wrp"><div class="experiences-btn"><?php $link = $item['link'] ?? array(); ?><a href="<?php echo esc_url( $link['url'] ?? '#' ); ?>"><i class="fa-solid fa-arrow-right"></i><?php echo esc_html( $item['title'] ?? '' ); ?></a><?php if ( ! empty( $item['description'] ) ) : ?><p><?php echo esc_html( $item['description'] ); ?></p><?php endif; ?></div></div></div><?php endforeach; ?></div><?php endif; ?></div></section>
